from pathlib import Path
import json,datetime,hashlib
P=Path(__file__).resolve().parent;sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
reg=json.loads((P/'registry/CURRENT-REGISTRIES.json').read_text())
urls=[]
for p in (P/'registry/current-bodies').rglob('*'):
 if p.is_file():
  rel=str(p.relative_to(P/'registry/current-bodies'));urls.append({'path':str(p.relative_to(P)),'url':'https://raw.githubusercontent.com/the-omega-institute/trureturing/'+reg['omega']['head']+'/'+rel,'observation_utc':reg['utc'],'sha256':sha(p),'acquisition':'root saved body; locally checked against saved tree blob'})
urls.append({'path':'registry/openai-CONTENTS.md','url':'https://raw.githubusercontent.com/openai/math/'+reg['openai']['head']+'/CONTENTS.md','observation_utc':reg['utc'],'sha256':sha(P/'registry/openai-CONTENTS.md')})
manifest={str(p.relative_to(P)):sha(p) for p in P.rglob('*') if p.is_file() and p.name not in ['provenance.json','provenance-build.log','provenance-build-guard.json']}
out={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'recommendation':'INVEST','current_prior':'BOUNDED_PASS','publisher_source':'PASS_FULL_BODY_AND_VISUAL_P356','credit':0,'campaign_counts':'7 additional / 37 total; root owns acceptance','scope':'targeted precise preliminary current-registry/source-version holds; no full math rerun, Lean or paper','current_registry_record':reg,'root_body_receipts':urls,'fresh_http':json.loads((P/'live/http.json').read_text()),'publisher_pdf_http':json.loads((P/'live/publisher-pdf-http.json').read_text()),'inherited_candidate_provenance':json.loads((P/'candidate/provenance.json').read_text()),'preliminary_receipts':{'review':'preliminary/review.md','http':'preliminary/live/http.json','note':'No standalone provenance file exists in preliminary review; its embedded receipts and saved representations retained.'},'checks':{'before':'freeze-before.json','after':'freeze-after.json','tree_body':'tree-body-checks.json'},'resource_policy':'All helpers through supplied capped_run.py: AS512MiB groupRSS512MiB sampledCPU210s wall230s sampling40ms BLAS1; no cap raised; sampling not continuous guarantee','access_limits':'No API limited-route retry, no alternate proxy, no bare .git reads or Git operations. Prior failures inherited, not erased. Springer PDF redirect error string preserved despite successful PDF bytes. Other registry screens search-only. Complete trees do not mean complete body coverage.','files_sha256':manifest}
(P/'provenance.json').write_text(json.dumps(out,indent=2)+'\n');print('manifest files',len(manifest),'provenance',sha(P/'provenance.json'))
